package com.tregy.backend.integrationtests.controller;
import com.tregy.backend.integrationtests.support.BaseIntegrationTest;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import tools.jackson.databind.json.JsonMapper;import java.util.Map;
import static org.hamcrest.Matchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AuthIntegrationTest extends BaseIntegrationTest{
 @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;private final JsonMapper json=JsonMapper.builder().build();
 @BeforeEach void clean(){jdbc.update("delete from password_reset_token");jdbc.update("delete from email_verification_token");jdbc.update("delete from refresh_token");jdbc.update("delete from device");jdbc.update("delete from app_user");}
 private String register(String email,String password)throws Exception{return json.writeValueAsString(Map.of("email",email,"password",password,"uiLanguage","it","installationId","install-a"));}
 @Test void shouldRegisterNormalizeEmailAndRejectDuplicate()throws Exception{mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(register(" Grace@example.com ","correct-horse-battery"))).andExpect(status().isCreated()).andExpect(jsonPath("$.email").value("grace@example.com")).andExpect(jsonPath("$.platformRole").value("USER")).andExpect(jsonPath("$.uiLanguage").value("it"));mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(register("grace@example.com","correct-horse-battery"))).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("EMAIL_ALREADY_EXISTS"));}
 @Test void shouldLoginRefreshAndAccessMe()throws Exception{mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(register("grace@example.com","correct-horse-battery"))).andExpect(status().isCreated());String login=json.writeValueAsString(Map.of("email","grace@example.com","password","correct-horse-battery","installationId","install-a"));String body=mvc.perform(post("/api/v1/auth/login").contentType("application/json").content(login)).andExpect(status().isOk()).andExpect(jsonPath("$.refreshToken",not(blankString()))).andReturn().getResponse().getContentAsString();String access=json.readTree(body).get("accessToken").asText();String refresh=json.readTree(body).get("refreshToken").asText();mvc.perform(get("/api/v1/me").header("Authorization","Bearer "+access)).andExpect(status().isOk()).andExpect(jsonPath("$.uiLanguage").value("it"));String request=json.writeValueAsString(Map.of("refreshToken",refresh));mvc.perform(post("/api/v1/auth/refresh").contentType("application/json").content(request)).andExpect(status().isOk()).andExpect(jsonPath("$.refreshToken",not(refresh)));}
 @Test void shouldUseSameResponseForUnknownRecoveryEmail()throws Exception{String request=json.writeValueAsString(Map.of("email","unknown@example.com"));mvc.perform(post("/api/v1/auth/forgot-password").contentType("application/json").content(request)).andExpect(status().isAccepted());mvc.perform(post("/api/v1/auth/resend-verification").contentType("application/json").content(request)).andExpect(status().isAccepted());}
 @Test void shouldRejectShortAndOver72BytePasswords()throws Exception{mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(register("short@example.com","short"))).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(register("long@example.com","é".repeat(37)))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));}
}
